<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import * as accountsAPI from '@shared-api/admin/accounts'
import * as groupsAPI from '@shared-api/admin/groups'
import * as proxiesAPI from '@shared-api/admin/proxies'
import type { Account, AccountPlatform, AccountType, AccountUsageInfo, AdminDataPayload, AdminGroup, CreateAccountRequest, Proxy, UpdateAccountRequest, WindowStats } from '@/types'
import ConsoleShell from '@/components/layout/ConsoleShell.vue'
import PageState from '@/components/base/PageState.vue'
import AccountEditorDialog from '@/components/admin/accounts/AccountEditorDialog.vue'
import AccountOAuthDialog from '@/components/admin/accounts/AccountOAuthDialog.vue'
import AccountWorkspaceDialog from '@/components/admin/accounts/AccountWorkspaceDialog.vue'
import AccountBulkDialog from '@/components/admin/accounts/AccountBulkDialog.vue'
import AccountToolsDialog from '@/components/admin/accounts/AccountToolsDialog.vue'
import AccountRuntimeCatalogDialog from '@/components/admin/accounts/AccountRuntimeCatalogDialog.vue'
import TotpStepUpDialog from '@/components/auth/TotpStepUpDialog.vue'
import { useStepUp, isStepUpBlocked, isStepUpCancelled } from '@/composables/useStepUp'
import { ConfirmTone, useConfirmStore } from '@/stores/confirm'
import { ResourceStatus, SortDirection, formatResourceDate } from '@/features/admin/resources/model'
import { useAppStore } from '@/stores/app'

enum AccountColumn { CAPACITY = 'capacity', TODAY = 'today', GROUPS = 'groups', USAGE = 'usage', UPSTREAM_RATE = 'upstream_rate', PROXY = 'proxy', NOTES = 'notes', PRIORITY = 'priority', SCHEDULER = 'scheduler', RATE = 'rate', LAST_USED = 'last_used', EXPIRES = 'expires' }
const columnLabels: Record<AccountColumn, string> = { [AccountColumn.CAPACITY]: '容量', [AccountColumn.TODAY]: '今日用量', [AccountColumn.GROUPS]: '绑定分组', [AccountColumn.USAGE]: '窗口用量', [AccountColumn.UPSTREAM_RATE]: '上游倍率', [AccountColumn.PROXY]: '代理', [AccountColumn.NOTES]: '备注', [AccountColumn.PRIORITY]: '优先级', [AccountColumn.SCHEDULER]: '调度分', [AccountColumn.RATE]: '计费倍率', [AccountColumn.LAST_USED]: '最近使用', [AccountColumn.EXPIRES]: '到期时间' }
const platformLabels: Record<AccountPlatform, string> = { openai: 'OpenAI / Codex', anthropic: 'Anthropic / Claude', gemini: 'Google Gemini', antigravity: 'Antigravity', grok: 'Grok', kimi: 'Kimi', zhipu: '智谱', deepseek: 'DeepSeek' }
const typeLabels: Record<AccountType, string> = { oauth: 'OAuth', 'setup-token': 'Setup Token', apikey: 'API Key', upstream: '上游账号', bedrock: 'Amazon Bedrock', service_account: 'Service Account' }
const statusLabels: Record<ResourceStatus, string> = { [ResourceStatus.ACTIVE]: '启用', [ResourceStatus.INACTIVE]: '停用', [ResourceStatus.ERROR]: '异常', [ResourceStatus.EXPIRED]: '已过期', [ResourceStatus.DISABLED]: '已禁用' }
const COLUMN_KEY = 'frontend2:admin-accounts:columns'; const FILTER_KEY = 'frontend2:admin-accounts:filters'; const PAGE_SIZES = [20, 50, 100]
const app = useAppStore(); const confirm = useConfirmStore(); const exportStepUp = useStepUp(); const accounts = ref<Account[]>([]); const groups = ref<AdminGroup[]>([]); const proxies = ref<Proxy[]>([]); const total = ref(0); const pages = ref(1); const page = ref(1); const pageSize = ref(20); const loading = ref(true); const secondaryLoading = ref(false); const error = ref(''); const etag = ref<string | null>(null)
const filters = reactive({ search: '', platform: '', type: '', status: '', group: '', privacy: '' }); const sort = reactive({ by: 'created_at', order: SortDirection.DESC }); const visibleColumns = ref(new Set<AccountColumn>([AccountColumn.CAPACITY, AccountColumn.GROUPS, AccountColumn.USAGE, AccountColumn.UPSTREAM_RATE, AccountColumn.LAST_USED])); const showColumns = ref(false); const selected = ref<number[]>([]); const todayStats = ref<Record<string, WindowStats>>({}); const usage = ref<Record<string, AccountUsageInfo>>({}); const autoRefresh = ref(0); let refreshTimer: number | null = null; let searchTimer: number | null = null; let controller: AbortController | null = null
const showEditor = ref(false); const editing = ref<Account | null>(null); const submitting = ref(false); const workspace = ref<Account | null>(null); const oauth = ref<Account | null>(null); const showBulk = ref(false); const bulkSubmitting = ref(false); const showTools = ref(false); const showCatalog = ref(false)
const selectedCount = computed(() => selected.value.length); const allPageSelected = computed(() => accounts.value.length > 0 && accounts.value.every(item => selected.value.includes(item.id))); const active = computed(() => accounts.value.filter(item => item.status === ResourceStatus.ACTIVE).length); const schedulable = computed(() => accounts.value.filter(item => item.schedulable).length); const currentConcurrency = computed(() => accounts.value.reduce((sum, item) => sum + (item.current_concurrency || 0), 0)); const maxConcurrency = computed(() => accounts.value.reduce((sum, item) => sum + item.concurrency, 0)); const todayRequests = computed(() => Object.values(todayStats.value).reduce((sum, item) => sum + item.requests, 0))
const platforms: AccountPlatform[] = ['openai', 'anthropic', 'gemini', 'antigravity', 'grok', 'kimi', 'zhipu', 'deepseek']; const types: AccountType[] = ['oauth', 'setup-token', 'apikey', 'upstream', 'bedrock', 'service_account']
function requestFilters() { return { platform: filters.platform || undefined, type: filters.type || undefined, status: filters.status || undefined, group: filters.group || undefined, search: filters.search.trim() || undefined, privacy_mode: filters.privacy || undefined, include_scheduler_score: visibleColumns.value.has(AccountColumn.SCHEDULER) ? 'true' : undefined, sort_by: sort.by, sort_order: sort.order } }
function hasColumn(column: AccountColumn): boolean { return visibleColumns.value.has(column) }
function toggleColumn(column: AccountColumn): void {
  const next = new Set(visibleColumns.value)
  if (next.has(column)) next.delete(column)
  else next.add(column)
  visibleColumns.value = next
  try { localStorage.setItem(COLUMN_KEY, JSON.stringify([...next])) } catch { /* optional */ }
  if (column === AccountColumn.SCHEDULER) { etag.value = null; void load() }
  else void loadSecondary()
}
function persistFilters(): void { try { localStorage.setItem(FILTER_KEY, JSON.stringify(filters)) } catch { /* optional */ } }
function restorePreferences(): void { try { const columns = localStorage.getItem(COLUMN_KEY); if (columns) visibleColumns.value = new Set(JSON.parse(columns) as AccountColumn[]); const saved = localStorage.getItem(FILTER_KEY); if (saved) Object.assign(filters, JSON.parse(saved)) } catch { /* defaults */ } }
async function loadReferences(): Promise<void> { const [groupResult, proxyResult] = await Promise.allSettled([groupsAPI.getAllIncludingInactive(), proxiesAPI.getAllWithCount()]); if (groupResult.status === 'fulfilled') groups.value = groupResult.value; if (proxyResult.status === 'fulfilled') proxies.value = proxyResult.value }
async function loadSecondary(force = false): Promise<void> { const ids = accounts.value.map(item => item.id); if (!ids.length || (!hasColumn(AccountColumn.TODAY) && !hasColumn(AccountColumn.USAGE))) return; secondaryLoading.value = true; const jobs: Promise<void>[] = []; if (hasColumn(AccountColumn.TODAY)) jobs.push(accountsAPI.getBatchTodayStats(ids).then(result => { todayStats.value = result.stats })); if (hasColumn(AccountColumn.USAGE)) jobs.push(accountsAPI.getBatchUsage(ids, force).then(result => { usage.value = result.usage; if (Object.keys(result.errors).length) app.showError(`${Object.keys(result.errors).length} 个账号用量加载失败`) })); await Promise.allSettled(jobs); secondaryLoading.value = false }
async function load(manual = false): Promise<void> { controller?.abort(); controller = new AbortController(); const current = controller; if (manual) etag.value = null; loading.value = accounts.value.length === 0; error.value = ''; persistFilters(); try { const response = await accountsAPI.listWithEtag(page.value, pageSize.value, requestFilters(), { signal: current.signal, etag: etag.value }); if (response.etag) etag.value = response.etag; if (!response.notModified && response.data) { accounts.value = response.data.items; total.value = response.data.total; pages.value = response.data.pages; selected.value = selected.value.filter(id => response.data!.items.some(item => item.id === id)); await loadSecondary() } } catch (caught) { if ((caught as { code?: string }).code !== 'ERR_CANCELED') error.value = (caught as { message?: string }).message || '账号加载失败' } finally { if (controller === current) loading.value = false } }
function searchLater(): void { if (searchTimer) window.clearTimeout(searchTimer); searchTimer = window.setTimeout(() => { page.value = 1; etag.value = null; void load() }, 280) }
function filter(): void { page.value = 1; etag.value = null; void load() }
function setSort(by: string): void {
  if (sort.by === by) sort.order = sort.order === SortDirection.ASC ? SortDirection.DESC : SortDirection.ASC
  else { sort.by = by; sort.order = SortDirection.ASC }
  etag.value = null
  void load()
}
function setAutoRefresh(seconds: number): void { autoRefresh.value = seconds; if (refreshTimer) window.clearInterval(refreshTimer); refreshTimer = seconds ? window.setInterval(() => void load(), seconds * 1000) : null }
function toggleSelect(id: number): void { selected.value = selected.value.includes(id) ? selected.value.filter(item => item !== id) : [...selected.value, id] }
function togglePage(): void { selected.value = allPageSelected.value ? selected.value.filter(id => !accounts.value.some(item => item.id === id)) : [...new Set([...selected.value, ...accounts.value.map(item => item.id)])] }
async function selectAllResults(): Promise<void> { if (total.value > 5000 && !await confirm.ask({ title: '选择全部筛选结果', message: `当前筛选有 ${total.value} 条，读取全部 ID 可能需要多次请求。`, confirmText: '继续' })) return; const ids: number[] = []; const batches = Math.ceil(total.value / 100); try { for (let current = 1; current <= batches; current += 1) ids.push(...(await accountsAPI.list(current, 100, requestFilters())).items.map(item => item.id)); selected.value = [...new Set(ids)]; app.showSuccess(`已选择 ${selected.value.length} 个账号`) } catch (caught) { app.showError((caught as { message?: string }).message || '选择全部失败') } }
function create(): void { editing.value = null; showEditor.value = true }
async function edit(account: Account): Promise<void> { try { editing.value = await accountsAPI.getById(account.id); showEditor.value = true } catch (caught) { app.showError((caught as { message?: string }).message || '账号详情加载失败') } }
async function save(payload: CreateAccountRequest | UpdateAccountRequest): Promise<void> { if (submitting.value) return; const platform = editing.value?.platform || (payload as CreateAccountRequest).platform; const groupIds = payload.group_ids || []; if (groupIds.length && (platform === 'antigravity' || platform === 'anthropic')) { try { const risk = await accountsAPI.checkMixedChannelRisk({ platform, group_ids: groupIds, account_id: editing.value?.id }); if (risk.has_risk && !await confirm.ask({ title: '混合渠道风险', message: risk.message || '这些分组可能连接到不同渠道，确认继续绑定？', confirmText: '确认继续', tone: ConfirmTone.DANGER })) return; if (risk.has_risk) payload.confirm_mixed_channel_risk = true } catch (caught) { app.showError((caught as { message?: string }).message || '混合渠道检查失败'); return } } submitting.value = true; try { if (editing.value) await accountsAPI.update(editing.value.id, payload as UpdateAccountRequest); else await accountsAPI.create(payload as CreateAccountRequest); app.showSuccess(editing.value ? '账号已更新' : '账号已创建'); showEditor.value = false; etag.value = null; await load() } catch (caught) { app.showError((caught as { message?: string }).message || '账号保存失败') } finally { submitting.value = false } }
async function toggleStatus(account: Account): Promise<void> { const next = account.status === 'active' ? 'inactive' : 'active'; if (next === 'inactive' && !await confirm.ask({ title: '停用上游账号', message: `停用 ${account.name} 后会立即退出调度池。`, confirmText: '停用', tone: ConfirmTone.DANGER })) return; try { await accountsAPI.toggleStatus(account.id, next); app.showSuccess(next === 'active' ? '账号已启用' : '账号已停用'); etag.value = null; await load() } catch (caught) { app.showError((caught as { message?: string }).message || '状态更新失败') } }
async function toggleSchedulable(account: Account): Promise<void> { try { await accountsAPI.setSchedulable(account.id, !account.schedulable); app.showSuccess(account.schedulable ? '账号已暂停调度' : '账号已恢复调度'); etag.value = null; await load() } catch (caught) { app.showError((caught as { message?: string }).message || '调度状态更新失败') } }
async function duplicate(account: Account): Promise<void> { try { await accountsAPI.duplicate(account.id); app.showSuccess(`已复制 ${account.name}`); etag.value = null; await load() } catch (caught) { app.showError((caught as { message?: string }).message || '复制失败') } }
async function remove(account: Account): Promise<void> { if (!await confirm.ask({ title: '删除上游账号', message: `确认永久删除 ${account.name}？关联凭据和运行时状态将一并移除。`, confirmText: '删除', tone: ConfirmTone.DANGER })) return; try { await accountsAPI.deleteAccount(account.id); app.showSuccess('账号已删除'); etag.value = null; await load() } catch (caught) { app.showError((caught as { message?: string }).message || '删除失败') } }
function operationSummary(result: { success: number; failed: number }): string { return `成功 ${result.success} 个，失败 ${result.failed} 个` }
async function batchAction(kind: 'delete' | 'clear' | 'refresh' | 'probe' | 'sched_on' | 'sched_off'): Promise<void> { if (!selected.value.length) return; const dangerous = kind === 'delete'; if ((dangerous || kind.startsWith('sched')) && !await confirm.ask({ title: dangerous ? '批量删除账号' : '批量修改调度状态', message: `将影响选中的 ${selected.value.length} 个账号。`, confirmText: dangerous ? '删除' : '确认', tone: dangerous ? ConfirmTone.DANGER : undefined })) return; bulkSubmitting.value = true; try { if (kind === 'probe') { const result = await accountsAPI.probeUpstreamBillingBatch(selected.value); app.showSuccess(`已完成 ${result.length} 个上游计费探测`) } else { const result = kind === 'delete' ? await accountsAPI.batchDelete(selected.value) : kind === 'clear' ? await accountsAPI.batchClearError(selected.value) : kind === 'refresh' ? await accountsAPI.batchRefresh(selected.value) : await accountsAPI.bulkUpdate(selected.value, { schedulable: kind === 'sched_on' }); app.showSuccess(operationSummary(result)) } selected.value = []; etag.value = null; await load() } catch (caught) { app.showError((caught as { message?: string }).message || '批量操作失败') } finally { bulkSubmitting.value = false } }
async function bulkUpdate(payload: Record<string, unknown>): Promise<void> { bulkSubmitting.value = true; try { const result = await accountsAPI.bulkUpdate(selected.value, payload); app.showSuccess(operationSummary(result)); showBulk.value = false; etag.value = null; await load() } catch (caught) { app.showError((caught as { message?: string }).message || '批量修改失败') } finally { bulkSubmitting.value = false } }
async function bulkCredential(field: string, value: unknown): Promise<void> { bulkSubmitting.value = true; try { const result = await accountsAPI.batchUpdateCredentials({ account_ids: selected.value, field, value }); app.showSuccess(`成功 ${result.success} 个，失败 ${result.failed} 个`); showBulk.value = false; etag.value = null; await load() } catch (caught) { app.showError((caught as { message?: string }).message || '凭据批量更新失败') } finally { bulkSubmitting.value = false } }
function downloadJson(payload: AdminDataPayload): void { const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `sub2api-accounts-${new Date().toISOString().slice(0, 10)}.json`; link.click(); URL.revokeObjectURL(url) }
async function exportData(includeProxies: boolean): Promise<void> { if (!await confirm.ask({ title: '导出账号敏感数据', message: selected.value.length ? `将导出选中的 ${selected.value.length} 个账号。下载文件可能包含可用凭据，请安全保存。` : '将按当前筛选导出全部匹配账号。下载文件可能包含可用凭据，请安全保存。', confirmText: '验证并下载' })) return; try { const payload = await exportStepUp.run(() => accountsAPI.exportData(selected.value.length ? { ids: selected.value, includeProxies } : { filters: requestFilters(), includeProxies })); downloadJson(payload); app.showSuccess('账号数据已下载') } catch (caught) { if (isStepUpCancelled(caught)) return; app.showError(isStepUpBlocked(caught) ? '当前会话无法完成二次验证。' : (caught as { message?: string }).message || '导出失败') } }
function groupNames(account: Account): string { return (account.groups || []).map(group => group.name).join('、') || (account.group_ids || []).map(id => groups.value.find(group => group.id === id)?.name || `#${id}`).join('、') || '未绑定' }
function quotaUsage(account: Account): string { const value = usage.value[String(account.id)]; if (!value) return secondaryLoading.value ? '加载中…' : '—'; const five = value.five_hour?.utilization; const seven = value.seven_day?.utilization; return `${five == null ? '—' : `${five.toFixed(0)}% / 5h`} · ${seven == null ? '—' : `${seven.toFixed(0)}% / 7d`}` }
function upstreamRate(account: Account): string { const snapshot = account.extra?.upstream_billing_probe; return snapshot?.synced_rate_multiplier == null ? '—' : `${snapshot.synced_rate_multiplier}×` }
onMounted(() => { restorePreferences(); void Promise.all([load(true), loadReferences()]) }); onBeforeUnmount(() => { controller?.abort(); if (searchTimer) window.clearTimeout(searchTimer); if (refreshTimer) window.clearInterval(refreshTimer) })
</script>

<template><ConsoleShell><main class="resource-page"><header class="resource-page__heading"><div><span class="resource-eyebrow">Upstream Fleet</span><h1>账号管理</h1><p>账号池的查询、调度、凭据、OAuth、配额、测试、导入导出和平台专项能力集中在同一高密度工作区。</p></div><button class="resource-button" data-tour="accounts-create-btn" @click="create">创建账号</button></header>
  <section class="resource-summary"><div><span>当前页 / 总数</span><strong>{{ accounts.length }} / {{ total }}</strong></div><div><span>启用 / 可调度</span><strong>{{ active }} / {{ schedulable }}</strong></div><div><span>实时并发</span><strong>{{ currentConcurrency }} / {{ maxConcurrency }}</strong></div><div><span>今日请求</span><strong>{{ todayRequests.toLocaleString() }}</strong></div></section>
  <section class="resource-toolbar"><div class="resource-toolbar__filters"><input v-model="filters.search" type="search" placeholder="搜索名称、备注、邮箱或账号 ID" @input="searchLater" /><select v-model="filters.platform" @change="filter"><option value="">全部平台</option><option v-for="item in platforms" :key="item" :value="item">{{ platformLabels[item] }}</option></select><select v-model="filters.type" @change="filter"><option value="">全部类型</option><option v-for="item in types" :key="item" :value="item">{{ typeLabels[item] }}</option></select><select v-model="filters.status" @change="filter"><option value="">全部状态</option><option value="active">启用</option><option value="inactive">停用</option><option value="error">异常</option></select><select v-model="filters.group" @change="filter"><option value="">全部分组</option><option v-for="group in groups" :key="group.id" :value="group.name">{{ group.name }}</option></select><select v-model="filters.privacy" @change="filter"><option value="">全部隐私状态</option><option value="set">已设置</option><option value="unset">未设置</option></select></div><div class="resource-toolbar__actions"><button class="resource-button resource-button--secondary" @click="load(true)">刷新</button><select :value="autoRefresh" aria-label="自动刷新" @change="setAutoRefresh(Number(($event.target as HTMLSelectElement).value))"><option :value="0">关闭自动刷新</option><option :value="10">每 10 秒</option><option :value="30">每 30 秒</option><option :value="60">每分钟</option></select><button class="resource-button resource-button--secondary" @click="showTools = true">导入与平台工具</button><button class="resource-button resource-button--secondary" @click="showCatalog = true">运行时规则库</button><button class="resource-button resource-button--secondary" @click="exportData(true)">导出{{ selectedCount ? ` ${selectedCount}` : '' }}</button><div class="column-control"><button class="resource-button resource-button--secondary" @click="showColumns = !showColumns">列设置</button><div v-if="showColumns" class="column-popover"><label v-for="column in Object.values(AccountColumn)" :key="column"><input type="checkbox" :checked="hasColumn(column)" @change="toggleColumn(column)" /> {{ columnLabels[column] }}</label></div></div></div></section>
  <aside v-if="selectedCount" class="selection-bar"><strong>已选 {{ selectedCount }} 个</strong><button @click="selectAllResults">选择全部 {{ total }} 个结果</button><button @click="showBulk = true">批量编辑</button><button @click="batchAction('clear')">清除错误</button><button @click="batchAction('refresh')">刷新凭据</button><button @click="batchAction('probe')">探测计费</button><button @click="batchAction('sched_on')">恢复调度</button><button @click="batchAction('sched_off')">暂停调度</button><button class="danger" @click="batchAction('delete')">批量删除</button><button @click="selected = []">取消选择</button></aside>
  <PageState :loading="loading" :error="error" :empty="!loading && !error && accounts.length === 0" empty-text="没有匹配的上游账号。" @retry="load(true)"><div class="resource-table account-table"><table><thead><tr><th class="resource-table__select"><input type="checkbox" :checked="allPageSelected" aria-label="选择当前页全部账号" @change="togglePage" /></th><th @click="setSort('name')">账号 ↕</th><th>平台 / 类型</th><th @click="setSort('status')">状态 ↕</th><th>调度</th><th v-if="hasColumn(AccountColumn.CAPACITY)">容量</th><th v-if="hasColumn(AccountColumn.TODAY)">今日</th><th v-if="hasColumn(AccountColumn.GROUPS)">分组</th><th v-if="hasColumn(AccountColumn.USAGE)">窗口用量</th><th v-if="hasColumn(AccountColumn.UPSTREAM_RATE)" @click="setSort('upstream_billing_rate')">上游倍率 ↕</th><th v-if="hasColumn(AccountColumn.PROXY)">代理</th><th v-if="hasColumn(AccountColumn.NOTES)">备注</th><th v-if="hasColumn(AccountColumn.PRIORITY)" @click="setSort('priority')">优先级 ↕</th><th v-if="hasColumn(AccountColumn.SCHEDULER)">调度分</th><th v-if="hasColumn(AccountColumn.RATE)" @click="setSort('rate_multiplier')">计费倍率 ↕</th><th v-if="hasColumn(AccountColumn.LAST_USED)" @click="setSort('last_used_at')">最近使用 ↕</th><th v-if="hasColumn(AccountColumn.EXPIRES)" @click="setSort('expires_at')">到期 ↕</th><th>操作</th></tr></thead><tbody><tr v-for="account in accounts" :key="account.id"><td><input type="checkbox" :checked="selected.includes(account.id)" :aria-label="`选择 ${account.name}`" @change="toggleSelect(account.id)" /></td><td><button class="resource-link account-name" @click="workspace = account">{{ account.name }}</button><small>#{{ account.id }}<template v-if="account.parent_account_id"> · 影子 / 母账号 #{{ account.parent_account_id }}</template></small></td><td><span class="resource-status">{{ platformLabels[account.platform] }}</span><small>{{ typeLabels[account.type] }}</small></td><td><button :class="['resource-status', `resource-status--${account.status}`]" @click="toggleStatus(account)">{{ statusLabels[account.status as ResourceStatus] || account.status }}</button><small v-if="account.error_message" class="resource-field-error" :title="account.error_message">{{ account.error_message }}</small></td><td><button :class="['resource-status', account.schedulable ? 'resource-status--active' : '']" @click="toggleSchedulable(account)">{{ account.schedulable ? '可调度' : '已暂停' }}</button><small v-if="account.rate_limit_reset_at">限流至 {{ formatResourceDate(account.rate_limit_reset_at) }}</small></td><td v-if="hasColumn(AccountColumn.CAPACITY)">{{ account.current_concurrency || 0 }} / {{ account.concurrency }}<small v-if="account.current_rpm != null">{{ account.current_rpm }} RPM</small></td><td v-if="hasColumn(AccountColumn.TODAY)">{{ todayStats[String(account.id)]?.requests || 0 }} 请求<small>${{ (todayStats[String(account.id)]?.cost || 0).toFixed(3) }}</small></td><td v-if="hasColumn(AccountColumn.GROUPS)">{{ groupNames(account) }}</td><td v-if="hasColumn(AccountColumn.USAGE)">{{ quotaUsage(account) }}</td><td v-if="hasColumn(AccountColumn.UPSTREAM_RATE)">{{ upstreamRate(account) }}<small>{{ account.extra?.upstream_billing_probe?.status || '未探测' }}</small></td><td v-if="hasColumn(AccountColumn.PROXY)">{{ account.proxy?.name || (account.proxy_id ? `#${account.proxy_id}` : '直连') }}<small v-if="account.proxy_fallback_origin_name">原：{{ account.proxy_fallback_origin_name }}</small></td><td v-if="hasColumn(AccountColumn.NOTES)">{{ account.notes || '—' }}</td><td v-if="hasColumn(AccountColumn.PRIORITY)">{{ account.priority }}</td><td v-if="hasColumn(AccountColumn.SCHEDULER)">{{ account.scheduler_score?.base_score ?? '—' }}<small>{{ account.scheduler_score?.sticky_weighted_enabled ? '粘性加权' : '基础' }}</small></td><td v-if="hasColumn(AccountColumn.RATE)">{{ account.rate_multiplier ?? 1 }}×</td><td v-if="hasColumn(AccountColumn.LAST_USED)">{{ formatResourceDate(account.last_used_at) }}</td><td v-if="hasColumn(AccountColumn.EXPIRES)">{{ formatResourceDate(account.expires_at) }}</td><td><div class="resource-inline-actions"><button class="resource-link" @click="workspace = account">工作台</button><button class="resource-link" @click="edit(account)">编辑</button><button v-if="['oauth','setup-token'].includes(account.type)" class="resource-link" @click="oauth = account">重授权</button><button class="resource-link" @click="duplicate(account)">复制</button><button class="resource-link resource-link--danger" @click="remove(account)">删除</button></div></td></tr></tbody></table></div></PageState>
  <footer class="resource-pagination"><span>共 {{ total }} 条 · 第 {{ page }} / {{ pages }} 页</span><div class="resource-pagination__actions"><select v-model.number="pageSize" @change="page = 1; etag = null; load()"><option v-for="size in PAGE_SIZES" :key="size" :value="size">{{ size }} / 页</option></select><button class="resource-button resource-button--secondary" :disabled="page <= 1" @click="page--; etag = null; load()">上一页</button><button class="resource-button resource-button--secondary" :disabled="page >= pages" @click="page++; etag = null; load()">下一页</button></div></footer>
  </main><AccountEditorDialog :show="showEditor" :account="editing" :groups="groups" :proxies="proxies" :submitting="submitting" @close="showEditor = false" @submit="save" /><AccountOAuthDialog :show="Boolean(oauth)" :account="oauth" @close="oauth = null" @updated="oauth = null; etag = null; load()" /><AccountWorkspaceDialog :show="Boolean(workspace)" :account="workspace" @close="workspace = null" @changed="etag = null; load()" /><AccountBulkDialog :show="showBulk" :count="selectedCount" :groups="groups" :proxies="proxies" :submitting="bulkSubmitting" @close="showBulk = false" @update="bulkUpdate" @credential="bulkCredential" /><AccountToolsDialog :show="showTools" :groups="groups" :proxies="proxies" @close="showTools = false" @changed="etag = null; load()" /><AccountRuntimeCatalogDialog :show="showCatalog" @close="showCatalog = false" /><TotpStepUpDialog :controller="exportStepUp" /></ConsoleShell></template>

<style scoped>.column-control { position: relative; }.column-popover { position: absolute; z-index: 7; right: 0; top: calc(100% + 5px); width: 190px; max-height: 330px; padding: 10px; overflow: auto; display: grid; gap: 7px; color: var(--text-secondary); background: var(--surface-raised); border: 1px solid var(--border-subtle); border-radius: 10px; box-shadow: 0 16px 44px rgba(0,0,0,.16); font-size: var(--font-meta); }.selection-bar { position: sticky; z-index: 4; top: 8px; padding: 10px 13px; display: flex; flex-wrap: wrap; align-items: center; gap: 8px; color: white; background: #191625; border-radius: 13px; box-shadow: 0 12px 34px rgba(10,8,20,.18); }.selection-bar button { padding: 6px 8px; color: inherit; background: rgba(255,255,255,.1); border: 0; border-radius: 7px; cursor: pointer; font-size: var(--font-meta); }.selection-bar .danger { color: #ffb1b1; }.account-table table { min-width: 1500px; }.account-name { padding-left: 0; color: var(--text-primary); font-size: 13px; }.account-table .resource-field-error { max-width: 150px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }</style>
